import json, csv, re
from collections import defaultdict
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
tmap = {t['rating_id']: t for t in tr}
mism = []
for r in rows:
    t = tmap.get(r['rating_id'])
    if t is None:
        mism.append(('missing', r)); continue
    m = re.findall(r'FINAL SCORE:\s*(\S+)', t['judge_output'])
    s_t = m[-1] if m else None
    da = re.search(r'Displayed author: (\S+?)\.', t['judge_output']).group(1)
    issues = []
    if str(t['session']) != r['session']: issues.append('session')
    if t['displayed_label'] != r['displayed_label']: issues.append('label')
    if da != r['displayed_label']: issues.append('author-in-text')
    if t['response_id'] != r['response_id']: issues.append('resp')
    if s_t != r['score']: issues.append(f'score {s_t} vs {r["score"]}')
    if t['judge_model'] != 'atlas-7': issues.append('judge_model '+t['judge_model'])
